from typing import Any, List

import pandas as pd
from langflow.custom import Component
from langflow.io import HandleInput, Output, TabInput
from langflow.schema import Data, DataFrame, Message


# --- Helper Functions (เหมือนเดิม แต่ปรับปรุงให้ Robust ขึ้น) ---
def convert_to_message(v) -> Message:
    if isinstance(v, Message):
        return v
    if isinstance(v, str):
        return Message(text=v)
    return v.to_message()


def convert_to_data(v: DataFrame | Data | Message | dict | str) -> Data:
    if isinstance(v, Data):
        return v
    if isinstance(v, dict):
        return Data(data=v)
    if isinstance(v, Message):
        return v.to_data()
    if isinstance(v, str):
        return Data(data={"text": v})
    return v.to_data()


def convert_to_dataframe(v: DataFrame | Data | Message | dict | str) -> DataFrame:
    if isinstance(v, DataFrame):
        return v
    if isinstance(v, dict):
        return DataFrame([v])
    if isinstance(v, str):
        return DataFrame([{"text": v}])
    return v.to_dataframe()


class TypeConverterComponent(Component):
    display_name = "Type Convert (Multi-Input)"
    description = "Convert and Merge inputs from multiple sources into a single type."
    icon = "merge" # เปลี่ยนไอคอนให้สื่อความหมาย
    name = "TypeConverter"

    inputs = [
        HandleInput(
            name="input_data",
            display_name="Input (Multi-Source)",
            input_types=["Message", "Data", "DataFrame", "Text"],
            info="Accepts multiple inputs. They will be merged/concatenated.",
            is_list=True, # สำคัญ: บอกว่ารับค่าเป็น List ได้
            required=True,
        ),
        TabInput(
            name="output_type",
            display_name="Output Type",
            options=["Message", "Data", "DataFrame"],
            info="Select the desired output data type",
            real_time_refresh=True,
            value="Message",
        ),
    ]

    outputs = [
        Output(
            display_name="Message Output",
            name="message_output",
            method="convert_to_message_list", # เปลี่ยนชื่อ method
        )
    ]

    def update_outputs(self, frontend_node: dict, field_name: str, field_value: Any) -> dict:
        """Dynamically show only the relevant output based on the selected output type."""
        if field_name == "output_type":
            frontend_node["outputs"] = []

            if field_value == "Message":
                frontend_node["outputs"].append(
                    Output(
                        display_name="Message Output",
                        name="message_output",
                        method="convert_to_message_list",
                    ).to_dict()
                )
            elif field_value == "Data":
                frontend_node["outputs"].append(
                    Output(
                        display_name="Data Output",
                        name="data_output",
                        method="convert_to_data_list",
                    ).to_dict()
                )
            elif field_value == "DataFrame":
                frontend_node["outputs"].append(
                    Output(
                        display_name="DataFrame Output",
                        name="dataframe_output",
                        method="convert_to_dataframe_merged",
                    ).to_dict()
                )

        return frontend_node

    def _flatten_input(self) -> List[Any]:
        """Helper to ensure input is a flat list of items."""
        # ตรวจสอบว่า input_data เป็น list หรือไม่ ถ้าไม่ให้แปลงเป็น list
        raw_inputs = self.input_data if isinstance(self.input_data, list) else [self.input_data]
        
        flat_list = []
        for item in raw_inputs:
            if isinstance(item, list):
                flat_list.extend(item)
            else:
                flat_list.append(item)
        return flat_list

    def convert_to_message_list(self) -> List[Message]:
        """Convert all inputs to a list of Messages."""
        inputs = self._flatten_input()
        result = [convert_to_message(item) for item in inputs]
        
        self.status = result
        return result

    def convert_to_data_list(self) -> List[Data]:
        """Convert all inputs to a list of Data objects."""
        inputs = self._flatten_input()
        result = [convert_to_data(item) for item in inputs]
        
        self.status = result
        return result

    def convert_to_dataframe_merged(self) -> DataFrame:
        """Convert all inputs to DataFrames and merge them into one."""
        inputs = self._flatten_input()
        
        dfs = []
        for item in inputs:
            try:
                df = convert_to_dataframe(item)
                if not df.empty:
                    dfs.append(df)
            except Exception:
                continue # Skip items that cannot be converted
        
        if not dfs:
            return DataFrame()
            
        # รวม DataFrame ทั้งหมดเข้าด้วยกัน (Concatenate)
        merged_df = pd.concat(dfs, ignore_index=True)
        
        self.status = merged_df
        return merged_df
